-- Read-only. Never returns identities, customer data, endpoints or private keys.
select jsonb_build_object(
 'projectMarker',(select project_ref from forno_private.production_environment),
 'counts',jsonb_build_object('pizzas',(select count(*) from public.pizzas),'services',(select count(*) from public.services),'slots',(select count(*) from public.pickup_slots),'orders',(select count(*) from public.orders),'admins',(select count(*) from forno_private.admin_users where active),'subscriptions',(select count(*) from forno_private.push_subscriptions where active)),
 'push',(select jsonb_build_object('enabled',enabled,'vapidReady',vapid_public_key is not null and vapid_secret_id is not null,'credentialPrepared',worker_hash is not null,'workerProjectMatches',worker_url='https://fqjkkjvrklpzhwmswlsy.supabase.co/functions/v1/forno-push-worker') from forno_private.push_config),
 'jobs',(select jsonb_agg(jsonb_build_object('name',jobname,'active',active,'schedule',schedule,'owner',username)) from cron.job),
 'browserPrivileges',(select count(*) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'forno_%' and(has_function_privilege('anon',p.oid,'execute') or has_function_privilege('authenticated',p.oid,'execute'))),
 'tableSecurity',(select jsonb_agg(jsonb_build_object('table',c.relname,'rls',c.relrowsecurity,'browserSelect',has_table_privilege('anon',c.oid,'select') or has_table_privilege('authenticated',c.oid,'select'))) from pg_class c join pg_namespace n on n.oid=c.relnamespace where c.relkind='r' and(n.nspname='forno_private' or(n.nspname='public' and c.relname in('orders','order_items'))))
) as production_postcheck;
select jsonb_build_object('pendingTtlMinutes',pending_ttl_minutes,'retentionDays',retention_days,'expiredPending',(select count(*) from public.orders where status='pending' and pending_expires_at<=clock_timestamp()),'purgeCandidatesByStatus',(select jsonb_object_agg(status,n) from(select status,count(*) n from public.orders where personal_data_purged_at is null and created_at<clock_timestamp()-make_interval(days=>s.retention_days) group by status)x),'pushMetadataRows',(select count(*) from forno_private.push_events),'auditRows',(select count(*) from forno_private.admin_audit)) as maintenance_effects from forno_private.settings s;
